#!/usr/bin/env node
// render_pr_body.js — deterministic PR body renderer for the apply-publish
// post-script (issue #210). Reads the engine run manifest (scc-manifest.json)
// and the stage record (ai-sdlc-run.json) from the working directory and
// writes the PR body to stdout. Pure function of its inputs — no network,
// no forge access; the write credential is never needed to render.
//
// Env: ISSUE (issue number for `Closes #N`), RUN_ID (workflow run id footer).
'use strict';

const fs = require('node:fs');

function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return {};
  }
}

function render({ manifest = {}, run = {}, issue = '', runId = '', engine = 'scc' } = {}) {
  const steps = manifest.tool_calls_total ?? manifest.steps ?? 'n/a';
  const fallback = run.fallback_used
    ? `yes — primary \`${run.primary_model}\` exited ${run.primary_exit} (${run.fallback_reason})`
    : 'no';
  const model = run.model ?? manifest.model ?? 'n/a';
  const gen = runId ? ` (run ${runId})` : '';
  return `## AI-SDLC autonomous implementation\n\n` +
    `Implements issue per \`.ai-sdlc.yaml\` contract.\n\n` +
    `**Run manifest:** model=\`${model}\` · fallback=${fallback} · steps=${steps} · ` +
    `engine=${engine} · audit log + \`ai-sdlc-run.json\` attached as workflow artifact.\n\n` +
    `Closes #${issue}\n\n` +
    `_Generated by ai-sdlc-implement${gen}_\n`;
}

if (require.main === module) {
  process.stdout.write(render({
    manifest: readJson('scc-manifest.json'),
    run: readJson('ai-sdlc-run.json'),
    issue: process.env.ISSUE || '',
    runId: process.env.RUN_ID || '',
    engine: process.env.ENGINE_ID || 'scc',
  }));
}

module.exports = { render, readJson };
